$_creator = "Mike Lu (lu.mike@inventec.com)"
$_version = '1.3'
$_changedate = '07/22/2026'

# Set-ExecutionPolicy Bypass

# ==============================================================================
# 0. 全域初始化與選單定義
# ==============================================================================

# 取得執行檔或腳本的真實物理目錄
function Get-ScriptDirectory {
    if ($env:PSExecutionPath) { return Split-Path -Parent $env:PSExecutionPath }
    try {
        $ProcPath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        if ($ProcPath -and $ProcPath -like "*.exe*") { return [System.IO.Path]::GetDirectoryName($ProcPath) }
    } catch {}
    if ($PSScriptRoot) { return $PSScriptRoot }
    if ($MyInvocation.MyCommand.Path) { return Split-Path $MyInvocation.MyCommand.Path -Parent }
    # 增加 .NET 核心保險路徑 (對打包成 EXE 的相容性極佳)
    return [System.AppContext]::BaseDirectory.TrimEnd('\')
}

# 切換目前工作目錄至腳本/EXE所在位置
$ScriptDirectory = Get-ScriptDirectory
if (-not [string]::IsNullOrEmpty($ScriptDirectory) -and (Test-Path -LiteralPath $ScriptDirectory)) {
    Set-Location -LiteralPath $ScriptDirectory
}

# 全域常數設定 (將版本資訊一併納入管理)
$GLOBAL_CONFIG = @{
    Version    = $_version
	SPTest_ver = "4.0.62.0"  # from SIO1925299
    SPTestExe  = "C:\HP Inc\SPTest\SPTest.exe"
    SPTestRoot = "C:\HP Inc\SPTest"
    SPQFolder  = Join-Path (Get-ScriptDirectory) "SPQ_files"
}

#region Base64 Payload 區塊
$GLOBAL_ManifestGenBase64 = ""
$GLOBAL_SPTestMsiBase64   = ""
#endregion



# 定義選單畫面
function Show-Menu {
    Write-Host ""
    Write-Host "** Windows Update & Softpaq Test **"
    Write-Host "                v$($GLOBAL_CONFIG.Version)" -ForegroundColor 'DarkYellow'
    Write-Host "======================================"
    Write-Host " [1] Get XML file"
    Write-Host " [2] Add reg key (before WU testing)"
    Write-Host " [3] Check event ID (after WU testing)"
    Write-Host " [4] Install and run SPTest"
    Write-Host " [5] Check SPTest log"
    Write-Host "======================================"
}

# ==============================================================================
# 1. 內部核心輔助函式 (Helper Functions)
# ==============================================================================

function Get-SafeFileSystemItems {
    param (
        [string]$Path,
        [string]$Filter = "*",
        [ValidateSet("File", "Directory")]
        [string]$Type = "File"
    )
    if (-not (Test-Path -LiteralPath $Path)) { return @() }
    
    try {
        $Items = if ($Type -eq "File") { 
            [System.IO.Directory]::GetFiles($Path, $Filter) 
        } else { 
            [System.IO.Directory]::GetDirectories($Path, $Filter) 
        }
        return @($Items | ForEach-Object { Get-Item -LiteralPath $_ })
    } catch {
        return @()
    }
}

# ==============================================================================
# 2. 主功能區塊 (Main Functions)
# ==============================================================================

# 功能 1: 獲取 XML 檔案
function Invoke-GetXml {    
    $TempExePath       = Join-Path $env:TEMP "systemmanifestgenerator.exe"
	# === 將 Base64 還原成實體 exe 檔案 ===
    try {
        # 解碼執行檔
        $ExeBytes = [System.Convert]::FromBase64String($GLOBAL_ManifestGenBase64)
        
        # 寫入暫存檔至 $TempExePath
        [System.IO.File]::WriteAllBytes($TempExePath, $ExeBytes)
        
        # 加入 -ArgumentList 來傳遞參數
        $Process = Start-Process -FilePath $TempExePath -ArgumentList "/output manifest.xml" -Wait -PassThru -NoNewWindow
        
        if ($Process.ExitCode -eq 0) {
            # 檢查檔案是否有成功產出在目前目錄
            if (Test-Path "manifest.xml") {
				Write-Host ""
                Write-Host "Done!" -ForegroundColor Green
				
            } else {
                Write-Host "Unable to find manifest.xml" -ForegroundColor Red
				Write-Host ""
            }
        } else {
            Write-Host "ERROR: $($Process.ExitCode)" -ForegroundColor Red
			Write-Host ""
        }
    } catch {
        Write-Host "ERROR: $_" -ForegroundColor Red
		Write-Host ""
    } finally {
        # 執行完畢後清理暫存檔
        if (Test-Path -LiteralPath $TempExePath) {
            Remove-Item -LiteralPath $TempExePath -Force -ErrorAction SilentlyContinue
        }
    }
}

# 功能 2: 加入Test registry key
function Invoke-AddTestRegistry {
    New-Item -Path "HKLM:\Software\Microsoft\DriverFlighting\Partner" -Force -ErrorAction SilentlyContinue | Out-Null
    Set-ItemProperty -Path "HKLM:\Software\Microsoft\DriverFlighting\Partner" -Name "TargetRing" -Value "Drivers" -Type String -Force
    Get-ItemProperty -Path "HKLM:\Software\Microsoft\DriverFlighting\Partner" -Name "TargetRing" -ErrorAction SilentlyContinue
    Write-Host ""
    Write-Host "Done!" -ForegroundColor Green
}

# 功能 3: 檢查Event ID 307
function Invoke-CheckEvent307 {
    try {
        Get-WinEvent -LogName 'Microsoft-Windows-DeviceUpdateAgent/Operational' -FilterXPath '*[System[(EventID=307)]]' -MaxEvents 1 -ErrorAction Stop |
            Select-Object TimeCreated, Id, Message | Format-List
    } catch {
        Write-Host "Error: $_" -ForegroundColor Red
    }
}

# 功能 4: 安裝並執行 SPTest
function Invoke-StartSPTest {
    # 1) 確保 SPTest 已安裝
    if (-not (Test-Path -LiteralPath $GLOBAL_CONFIG.SPTestExe)) {
        $TempMsiPath = Join-Path $env:TEMP "SPTestInstaller_$([Guid]::NewGuid().Guid).msi"
        try {
            Write-Host "Installing SPTest tool..."
            $Bytes = [Convert]::FromBase64String($GLOBAL_SPTestMsiBase64)
            [System.IO.File]::WriteAllBytes($TempMsiPath, $Bytes)
            
            $MsiArgs = @("/i", "`"$TempMsiPath`"", "/quiet")
            $Process = Start-Process -FilePath "msiexec.exe" -ArgumentList $MsiArgs -Wait -PassThru
            if ($Process.ExitCode -ne 0) {
                Write-Host "SPTest install failed. msiexec exit code: $($Process.ExitCode)" -ForegroundColor Red
                return
            }
        } 
        catch { Write-Host "Failed to extract MSI installer: $_" -ForegroundColor Red; return }
        finally {
            if (Test-Path -LiteralPath $TempMsiPath) {
                Remove-Item -LiteralPath $TempMsiPath -Force -ErrorAction SilentlyContinue
            }
        }

        if (-not (Test-Path -LiteralPath $GLOBAL_CONFIG.SPTestExe)) {
            Write-Host "SPTest install finished, but SPTest.exe still not found." -ForegroundColor Red
            return
        }
        Write-Host "SPTest installed successfully." -ForegroundColor Green
    } else {
        Write-Host "SPTest already installed. Skipping install." -ForegroundColor DarkGray
    }
	
	# 初始化 SPQ 目錄
    if (-not (Test-Path -LiteralPath $GLOBAL_CONFIG.SPQFolder)) {
        New-Item -ItemType Directory -Path "$($GLOBAL_CONFIG.SPQFolder)" -Force | Out-Null
        Write-Host "Folder 'SPQ_files' was not found. Automatically created." -ForegroundColor Yellow
        Write-Host "Please place your spXXXXXX.exe and spXXXXXX.cva files into: $($GLOBAL_CONFIG.SPQFolder)" -ForegroundColor Yellow
        return
    }

    # 2) 驗證 SPQ 檔案配對
    $ExeFiles = Get-SafeFileSystemItems -Path $GLOBAL_CONFIG.SPQFolder -Filter "sp*.exe"
    $CvaFiles = Get-SafeFileSystemItems -Path $GLOBAL_CONFIG.SPQFolder -Filter "sp*.cva"

    if ($ExeFiles.Count -eq 0 -or $CvaFiles.Count -eq 0) {
        Write-Host "Missing EXE or CVA files in $($GLOBAL_CONFIG.SPQFolder)" -ForegroundColor Red
        return
    }

    $ExeBases = @($ExeFiles | ForEach-Object { $_.BaseName.ToLowerInvariant() })
    $CvaBases = @($CvaFiles | ForEach-Object { $_.BaseName.ToLowerInvariant() })
    $Pairs    = @($ExeBases | Where-Object { $CvaBases -contains $_ } | Select-Object -Unique)

    if ($Pairs.Count -eq 0 -or $Pairs.Count -gt 1 -or $ExeFiles.Count -ne 1 -or $CvaFiles.Count -ne 1) {
        Write-Host "Verification failed: Ensure exactly ONE matching pair of spXXXXXX.exe/.cva exists." -ForegroundColor Red
        return
    }

    $SpBase = $Pairs[0]
    $ExeFile = $ExeFiles | Where-Object { $_.BaseName.ToLowerInvariant() -eq $SpBase } | Select-Object -First 1
    $CvaFile = $CvaFiles | Where-Object { $_.BaseName.ToLowerInvariant() -eq $SpBase } | Select-Object -First 1

    # 3) 建立目的地並複製檔案
    $DestDir = Join-Path $GLOBAL_CONFIG.SPTestRoot $SpBase
    New-Item -ItemType Directory -Path "$DestDir" -Force | Out-Null

    Copy-Item -LiteralPath $ExeFile.FullName -Destination (Join-Path $DestDir $ExeFile.Name) -Force
    Copy-Item -LiteralPath $CvaFile.FullName -Destination (Join-Path $DestDir $CvaFile.Name) -Force
    Write-Host "Copied $($ExeFile.Name) and $($CvaFile.Name) to $DestDir" -ForegroundColor Green

    # 4) 執行 SPTest 狀態判斷
    $LaunchFlag = Join-Path $ScriptDirectory ".sptest_launch.flag"
    Write-Host ""
    
    if (-not (Test-Path -LiteralPath $LaunchFlag)) {
        # ==========================
        # 第一次執行 (1/2)
        # ==========================
        Write-Host "Launching SPTest (1/2)..." -ForegroundColor Cyan
        
        # 建立 Flag 檔案標記已經跑過第一次
        New-Item -ItemType File -Path "$LaunchFlag" -Force | Out-Null
        
        # 啟動行程並強制等待
        $p = Start-Process -FilePath $GLOBAL_CONFIG.SPTestExe -ArgumentList @("/spq", $SpBase) -WorkingDirectory $GLOBAL_CONFIG.SPTestRoot -PassThru
        if ($p) {
            $p | Wait-Process -ErrorAction SilentlyContinue
        }
        
        # 額外保險：如果它有背景子行程叫 SPTest，持續監控直到完全消失
        while (Get-Process -Name "SPTest" -ErrorAction SilentlyContinue) {
            Start-Sleep -Seconds 1
        }
        
        # 顯示提示訊息
        Write-Host "`n*System will automatically reboot in a few seconds*" -ForegroundColor Yellow
    } 
    else {
        # ==========================
        # 第二次執行 (2/2)
        # ==========================
        Write-Host "Launching SPTest (2/2)..." -ForegroundColor Cyan
        
        # 啟動行程並強制等待
        $p = Start-Process -FilePath $GLOBAL_CONFIG.SPTestExe -ArgumentList @("/spq", $SpBase) -WorkingDirectory $GLOBAL_CONFIG.SPTestRoot -PassThru
        if ($p) {
            $p | Wait-Process -ErrorAction SilentlyContinue
        }
        
        # 額外保險：持續監控直到 SPTest 行程完全消失
        while (Get-Process -Name "SPTest" -ErrorAction SilentlyContinue) {
            Start-Sleep -Seconds 1
        }
        
        # 移除 Flag 檔案
        Remove-Item -LiteralPath $LaunchFlag -Force -ErrorAction SilentlyContinue
        
        # 顯示第二次執行完畢的提示
        Write-Host "`nDone!" -ForegroundColor Green
    }
    
    Write-Host ""
}

# 功能 5: 檢查 SPTest Log
function Invoke-CheckSPTestLog {
    if (-not (Test-Path -LiteralPath $GLOBAL_CONFIG.SPTestRoot)) {
        Write-Host "Folder not found: $($GLOBAL_CONFIG.SPTestRoot)" -ForegroundColor Red
        return
    }

    # 掃描並篩選符合名稱的子目錄
    $SpDirs = Get-SafeFileSystemItems -Path $GLOBAL_CONFIG.SPTestRoot -Type "Directory" | 
              Where-Object { $_.Name -match '^sp\d{6,}$' }

    if ($SpDirs.Count -eq 0) {
        Write-Host "No spXXXXXX folder found under $($GLOBAL_CONFIG.SPTestRoot)" -ForegroundColor Red
        return
    }
    if ($SpDirs.Count -gt 1) {
        Write-Host "Multiple folders found! Please keep only one for log checking." -ForegroundColor Red
        return
    }

    $SpDir   = $SpDirs[0]
    $LogFile = Join-Path $SpDir.FullName "$($SpDir.Name).log"
    if (-not (Test-Path -LiteralPath $LogFile)) {
        Write-Host "Log file not found: $LogFile" -ForegroundColor Red
        return
    }

    $Content = Get-Content -LiteralPath $LogFile -ErrorAction Stop
    
    function Get-StatusLineValue([string[]]$lines, [string]$prefix) {
        $line = $lines | Where-Object { $_ -match ("^\s*" + [regex]::Escape($prefix) + "\s*") } | Select-Object -First 1
        if (-not $line) { return $null }
        return ($line -replace ("^\s*" + [regex]::Escape($prefix) + "\s*"), "").Trim()
    }

    function Normalize([string]$s) {
        if ($null -eq $s) { return $null }
        return ($s.Trim().TrimEnd('.')).ToUpperInvariant()
    }

    function Write-CheckResult([string]$label, [string]$actual, [string]$expectedNorm) {
        $actualNorm = Normalize $actual
        $ok = ($actualNorm -eq $expectedNorm)
        $color = if ($ok) { "Green" } else { "Red" }
        $show = if ($null -eq $actual) { "<NOT FOUND>" } else { $actual.Trim() }
        
        Write-Host ($label + " ") -NoNewline
        Write-Host $show -ForegroundColor $color
    }

    $overall = Get-StatusLineValue -lines $Content -prefix "Overall Status:"
    $cvaInt  = Get-StatusLineValue -lines $Content -prefix "CVA Integrity Check:"
    $target  = Get-StatusLineValue -lines $Content -prefix "Targeting Check:"
    $install = Get-StatusLineValue -lines $Content -prefix "Installation Check:"

    $expectedOverall = "REBOOT REQUIRED & PASS"
    $expectedPass    = "PASS"

    Write-Host "`nLog file: $LogFile`n" -ForegroundColor Yellow
    
    Write-CheckResult -label "Overall Status:" -actual $overall -expectedNorm (Normalize $expectedOverall)
    Write-CheckResult -label "CVA Integrity Check:" -actual $cvaInt -expectedNorm (Normalize $expectedPass)
    Write-CheckResult -label "Targeting Check:" -actual $target -expectedNorm (Normalize $expectedPass)
    Write-CheckResult -label "Installation Check:" -actual $install -expectedNorm (Normalize $expectedPass)
    
    Write-Host ""
}

# ==============================================================================
# 3. 核心主流程控制 
# ==============================================================================
do {
    Show-Menu  # 呼叫上方定義的選單
    
    # 定義可接受的正確選項 (如果你有 'q' 或 'Q' 離開的選項，請加進這個陣列中)
    $validChoices = @('1', '2', '3', '4', '5')
    
    $input = Read-Host "Please enter your choice"
    
    # 只要輸入的值不在 $validChoices 陣列裡面，就持續要求重新輸入
    while ($input -notin $validChoices) {
        Write-Host "Invalid option" -ForegroundColor Yellow
        $input = Read-Host "Please enter your choice"
    }
    
    # 執行到這裡時，代表 $input 絕對是合法的值，可以安全進入 switch
    switch ($input) {
        '1' {
            Write-Host "`n=== Get system manifest log ===" -ForegroundColor Cyan
            Invoke-GetXml
        }
        '2' {
            Write-Host "`n=== Add test registry key ===" -ForegroundColor Cyan
            Invoke-AddTestRegistry
        }
        '3' {
            Write-Host "`n=== Check event ID 307 ===" -ForegroundColor Cyan
            Invoke-CheckEvent307
        }
        '4' {
            Write-Host "`n=== Install and run SPTest v$($GLOBAL_CONFIG.SPTest_ver) ===" -ForegroundColor Cyan
            Invoke-StartSPTest
        }
        '5' {
            Write-Host "`n=== Check SPTest log ===" -ForegroundColor Cyan
            Invoke-CheckSPTestLog
        }
    }
    
	# 稍微停頓 0.5 秒，讓系統行程完全穩定切換回 PowerShell 視窗
    Start-Sleep -Milliseconds 500

    # 清空可能殘留在鍵盤緩衝區的按鍵，防止自動被略過
    while ($Host.UI.RawUI.KeyAvailable) {
        [void]$Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
    }

    Write-Host "`nPress any key to continue..." -ForegroundColor Gray
    [void]$Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
    
    Clear-Host

} while ($true)
	

